package android.view;
public class ViewGroup extends View { java.util.List<View> children=new java.util.ArrayList<>(); public ViewGroup(android.content.Context c){super(c);} public static class LayoutParams {public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2; public int width,height; public LayoutParams(int w,int h){width=w;height=h;} } public void addView(View v){children.add(v);} public void addView(View v,LayoutParams p){v.setLayoutParams(p);children.add(v);} public void addView(View v,int i,LayoutParams p){v.setLayoutParams(p);children.add(i,v);} public void removeView(View v){children.remove(v);} public int getChildCount(){return children.size();} public View getChildAt(int i){return children.get(i);} public View findViewWithTag(Object t){View own=super.findViewWithTag(t);if(own!=null)return own;for(View v:children){View found=v.findViewWithTag(t);if(found!=null)return found;}return null;} }
